save(94,dict(paragraphs=["Ketaki Datta is a poet, novelist, translator and literary reviewer with a background in teaching English in Kolkata. Her writing moves between original fiction and poetry, literary criticism and translation. Her collections include Across the Blue Horizon and The Music of Eternity; Urban Reflections brings her poems into conversation with Wilfried Raussert’s photographs.","In her Kabita Live poem ‘Pinpointing the emotions’, she asks whether anguish can be located as precisely as a chamber of the heart. The questions widen into the distinctions between loneliness and solitude, waiting and endurance. Autumn leaves, birds, still water and trembling dew carry the poem back towards remembered days of celebration."],sources=[source('Setu — Ketaki Datta contributor biography, July 2020','https://www.setumag.com/2020/07/new-discoveries-ketaki-datta.html',['English teaching in Kolkata; literary genres; Across the Blue Horizon; Urban Reflections collaboration']),source('Penprints — poetry catalogue','https://penprints.in/shop/product-category/poetry/',['The Music of Eternity, author Ketaki Datta, ISBN 9788195619719; catalogue year 2022'])],identity_match='Kolkata English academic, translator and distinctive poetry titles/collaboration agree with the captured biography.',poems_read=[dict(id=73,title='Pinpointing the emotions',basis='Full source read: anatomical questions, distinctions between emotions, autumn, birds, still water and recollected gaiety.')],limitations=['Older contributor biography not used to assert current academic rank or employer.','Publisher author note elsewhere says 2023 for Music of Eternity, while specific catalogue and 2022 reviews say 2022; year omitted from narrative.','Individual publisher product link did not open; no book card added.'],next_action='Independent author/editor review; verify a stable individual book destination.'))
